import{_ as o,c as e,o as d,ag as r}from"./chunks/framework.DPDPlp3K.js";const u=JSON.parse('{"title":"Agent instructions · 瓦罐 / 猎装旅行车图鉴","description":"","frontmatter":{},"headers":[],"relativePath":"notion/AGENTS.md","filePath":"notion/AGENTS.md"}'),a={name:"notion/AGENTS.md"};function n(i,t,l,s,c,g){return d(),e("div",null,t[0]||(t[0]=[r('<h1 id="agent-instructions-·-瓦罐-猎装旅行车图鉴" tabindex="-1">Agent instructions · 瓦罐 / 猎装旅行车图鉴 <a class="header-anchor" href="#agent-instructions-·-瓦罐-猎装旅行车图鉴" aria-label="Permalink to &quot;Agent instructions · 瓦罐 / 猎装旅行车图鉴&quot;">​</a></h1><blockquote><p><strong>给 Cursor / 其他 agent：</strong> 维护本项目前先读完本文。<br> 单页图鉴：同目录 <code>wagon-shooting-brake-gallery.html</code><br> 本文件与 HTML 始终相对同目录；<strong>不要写死绝对路径</strong>（目录可能搬家）。</p></blockquote><p>HTML 文件顶部有 <code>&lt;!-- AGENT_RULES --&gt;</code> 注释块（入口摘要 + 指向本文）；script 内仅保留一行指向。<strong>以本文件 <code>AGENTS.md</code> 为完整规范源</strong>。</p><hr><h2 id="_1-项目是什么" tabindex="-1">1. 项目是什么 <a class="header-anchor" href="#_1-项目是什么" aria-label="Permalink to &quot;1. 项目是什么&quot;">​</a></h2><ul><li>单文件 HTML 图鉴：全球 + 中国相关的 <strong>station wagon / estate / 旅行版（瓦罐）</strong> 与 <strong>shooting brake（猎装）</strong>。</li><li>图片全部为 <strong>Wikimedia Commons / Wikipedia 外链</strong>，不下载到本地、不使用需鉴权图床。</li><li>支持搜索、筛选、排序、本地收藏 / 笔记 /「图不对」标记（localStorage）。</li><li>浏览器直接打开 HTML 即可；非 ecoflow-tech 仓库业务代码。</li></ul><hr><h2 id="_2-改动原则" tabindex="-1">2. 改动原则 <a class="header-anchor" href="#_2-改动原则" aria-label="Permalink to &quot;2. 改动原则&quot;">​</a></h2><ol><li><strong>优先新增</strong>：新车 → 往 <code>CARS</code> 数组加对象；新 UI → 尽量加控件/样式，少改无关逻辑。</li><li><strong>用户没要求就不要</strong>：全表重命名、大重构、主动 <code>git commit</code> / push。</li><li><strong>改到哪条规范哪条</strong>：历史命名未全部对齐时，只规范本次触及的条目。</li><li><strong>分卡优于混名</strong>：官方就是两款车（如 V90 vs V90 Cross Country）→ 两张卡 + <code>note</code> 互指，不要合成模糊标题。</li></ol><hr><h2 id="_3-命名规范-必须遵守" tabindex="-1">3. 命名规范（必须遵守） <a class="header-anchor" href="#_3-命名规范-必须遵守" aria-label="Permalink to &quot;3. 命名规范（必须遵守）&quot;">​</a></h2><h3 id="字段" tabindex="-1">字段 <a class="header-anchor" href="#字段" aria-label="Permalink to &quot;字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>id</code></td><td>小写短横线：<code>品牌简-车系-提示</code>（如 <code>mb-e63-estate</code>, <code>volvo-v90-cc</code>）</td></tr><tr><td><code>name</code></td><td>英文主名</td></tr><tr><td><code>name_zh</code></td><td>中文主名（卡片大标题）</td></tr><tr><td><code>type</code></td><td><code>wagon</code> | <code>shooting_brake</code>（筛选分类）</td></tr><tr><td><code>era</code></td><td><code>pioneer</code> | <code>classic</code> | <code>modern</code></td></tr><tr><td><code>region</code></td><td><code>cn</code> | <code>eu</code> | <code>uk</code> | <code>us</code> | <code>jp</code> | <code>au</code></td></tr><tr><td><code>year</code> / <code>year_end</code></td><td>年代（排序默认 <strong>新→旧</strong>）</td></tr><tr><td><code>note</code></td><td>官方别名、国内外差异、世代、配图说明</td></tr><tr><td><code>tags</code></td><td>搜索别名（桑旅、z9gt、t-modell…）</td></tr><tr><td><code>image</code> / <code>image_full</code></td><td>Commons <strong>直链</strong> <code>https://upload.wikimedia.org/...</code></td></tr><tr><td><code>image_credit</code></td><td><code>Wikimedia: 完整文件名</code></td></tr></tbody></table><h3 id="英文-name" tabindex="-1">英文 <code>name</code> <a class="header-anchor" href="#英文-name" aria-label="Permalink to &quot;英文 `name`&quot;">​</a></h3><p>格式：<code>Brand + Model + Official body name</code></p><p>官方车身名对照（优先跟厂家该市场用语）：</p><table tabindex="0"><thead><tr><th>体系</th><th>车身官方名</th></tr></thead><tbody><tr><td>Mercedes-Benz</td><td><strong>T-Modell</strong>（德）/ <strong>Estate</strong>（英）；北美偶称 Wagon</td></tr><tr><td>Mercedes 猎装</td><td><strong>Shooting Brake</strong>（不是 T-Modell）</td></tr><tr><td>Mercedes 性能</td><td><strong>Mercedes-AMG …</strong>（性能子品牌，仍属奔驰体系）</td></tr><tr><td>BMW</td><td><strong>Touring</strong>；M 系写 <strong>BMW M5 Touring</strong></td></tr><tr><td>Audi</td><td><strong>Avant</strong></td></tr><tr><td>Volkswagen</td><td><strong>Variant</strong></td></tr><tr><td>Volvo</td><td>V60/V70/V90 等本身即旅行车；抬高版写全称 <strong>Cross Country</strong> 并分卡</td></tr><tr><td>Peugeot / Citroën</td><td><strong>Break</strong></td></tr><tr><td>Škoda</td><td><strong>Combi</strong></td></tr><tr><td>Opel</td><td><strong>Caravan</strong> / <strong>Sports Tourer</strong></td></tr><tr><td>美系</td><td><strong>Wagon</strong> / <strong>Estate</strong>（按该车常见官方称呼）</td></tr><tr><td>猎装 / 超跑旅行</td><td>Shooting Brake / Sport Turismo / Sportbrake（跟厂家）</td></tr></tbody></table><p>斜杠 <code>A / B</code> 仅用于同一车身的官方双语（如 <code>T-Modell / Estate</code>），不要堆俗称。</p><h3 id="中文-name-zh" tabindex="-1">中文 <code>name_zh</code> <a class="header-anchor" href="#中文-name-zh" aria-label="Permalink to &quot;中文 `name_zh`&quot;">​</a></h3><p>格式：<code>品牌通称 + 车系常用名 + 统一后缀</code></p><ul><li>旅行车 / 瓦罐 → 后缀 <strong>「旅行版」</strong>（<code>type=wagon</code>）</li><li>猎装 → <strong>「猎装」</strong> 或保留厂家专名（Shooting Brake、Sportbrake、Z9 GT…）</li><li>品牌：奔驰（舒适线）/ <strong>梅赛德斯-AMG</strong>（AMG 性能线）；宝马、奥迪、大众、沃尔沃…</li><li>车系用国内认知名（帕萨特、明锐、海豹06、享界…）</li><li>官方英文专名可保留在中文名中（Avant、T-Modell、ET5T）</li><li><strong>不要</strong>用「瓦罐 / Wagon / Estate」当中文统一后缀（这些放 <code>note</code> 或英文名）</li></ul><h3 id="世代-市场-国产进口" tabindex="-1">世代 / 市场 / 国产进口 <a class="header-anchor" href="#世代-市场-国产进口" aria-label="Permalink to &quot;世代 / 市场 / 国产进口&quot;">​</a></h3><ul><li><strong>不要</strong>塞进主名正文；用括号短注或只写在 <code>note</code></li><li>例：马自达6 三代国内仅引进初代 GG → 分卡并在 note 写清海外 GH/GJ</li></ul><hr><h2 id="_4-图片规范" tabindex="-1">4. 图片规范 <a class="header-anchor" href="#_4-图片规范" aria-label="Permalink to &quot;4. 图片规范&quot;">​</a></h2><ol><li>只用 Wikimedia Commons（或 Wikipedia 指向 Commons）的 <strong>upload.wikimedia.org</strong> 直链。</li><li>禁止：随意 Flickr、需登录图床、<code>Special:FilePath</code> 长期占位、轿车图冒充旅行版、灵车/警车（除非注明）。</li><li>搜图：Commons API；注意 429，降低频率。</li><li>无可靠瓦罐图时：<code>image</code> 置空，靠 UI「暂无图片」占位，并在 <code>note</code> 写明待补——<strong>不要</strong>用明显错误车型图凑数。</li><li>用户点「图不对」→ 导出 JSON 的 <code>flagged</code> 列表优先修。</li></ol><hr><h2 id="_5-ui-行为约定-勿随便改默认" tabindex="-1">5. UI / 行为约定（勿随便改默认） <a class="header-anchor" href="#_5-ui-行为约定-勿随便改默认" aria-label="Permalink to &quot;5. UI / 行为约定（勿随便改默认）&quot;">​</a></h2><ul><li>默认排序：<strong>年代新 → 旧</strong>（<code>sort=year-desc</code>）</li><li>排序控件：新→旧 / 旧→新 / 中文名 / 英文名 / 地区 / 类型</li><li>收藏、笔记、「图不对」存 <code>localStorage</code> key：<code>wagon_gallery_v1</code></li><li>导出 JSON 含 <code>store</code> + <code>flagged</code> 摘要</li></ul><hr><h2 id="_6-常见产品知识-避免再搞混" tabindex="-1">6. 常见产品知识（避免再搞混） <a class="header-anchor" href="#_6-常见产品知识-避免再搞混" aria-label="Permalink to &quot;6. 常见产品知识（避免再搞混）&quot;">​</a></h2><ul><li><strong>Volvo V90</strong>（标准旅行）与 <strong>V90 Cross Country</strong>（抬高）是两款 → 两张卡；国内更常见 CC。</li><li><strong>奔驰</strong> 旅行官方名是 T-Modell/Estate；<strong>AMG E 63</strong> 是同体系性能旅行，不是另一个无关牌子。</li><li><strong>本田豪华牌</strong> 类比雷克萨斯 → <strong>讴歌 Acura</strong>；AMG 更像 BMW M，不是独立豪华牌。</li><li><strong>享界 S9T</strong>（Stelato）、<strong>尚界 Z7T</strong>、<strong>海豹06DM-i旅行版</strong>、<strong>腾势 Z9 GT</strong>、<strong>风云 A9 Wagon</strong>（亮相/待量产）等已按国产新能源旅行/猎装收录逻辑处理。</li><li><strong>奇瑞风云 A9</strong> 轿车 ≠ <strong>A9 Wagon</strong>；图鉴应收 Wagon，无 Commons 瓦罐图就留空。</li></ul><hr><h2 id="_7-新增一辆车的检查清单" tabindex="-1">7. 新增一辆车的检查清单 <a class="header-anchor" href="#_7-新增一辆车的检查清单" aria-label="Permalink to &quot;7. 新增一辆车的检查清单&quot;">​</a></h2><ol><li>确认是 wagon / shooting brake（或厂家明确的 Touring / T / Wagon / 猎装）。</li><li>按命名规范写 <code>name</code> / <code>name_zh</code> / <code>note</code> / <code>tags</code>。</li><li>Commons 找到<strong>匹配车身</strong>的外景图 → 直链写入。</li><li>插入 <code>CARS</code> 时靠近同品牌或同地区现代车（可读性），不依赖数组顺序（默认按年排序）。</li><li>必要时更新本 <code>AGENTS.md</code> 第 6 节「常见产品知识」。</li></ol><hr><h2 id="_8-文件索引" tabindex="-1">8. 文件索引 <a class="header-anchor" href="#_8-文件索引" aria-label="Permalink to &quot;8. 文件索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td><strong>本文件</strong>：agent 完整提示词 / rules</td></tr><tr><td><code>wagon-shooting-brake-gallery.html</code></td><td>图鉴本体；顶部 <code>AGENT_RULES</code> + script 一行指向本文</td></tr></tbody></table><p>不要把本项目规则写进 ecoflow-tech 仓库；本目录是独立 Downloads 小项目。</p>',39)]))}const m=o(a,[["render",n]]);export{u as __pageData,m as default};
